/* billing.h */
typedef struct svc svc_t;                  /* opaque delegate handle */
svc_t *svc_open(const char *endpoint);     /* lookup + transport setup */
int    svc_call(svc_t *s, const char *op, const char *in, char **out);
void   svc_close(svc_t *s);                /* releases transport and cache */
/* billing.c */
struct svc { const struct transport_ops *ops; void *conn; int last_errno; };
int svc_call(svc_t *s, const char *op, const char *in, char **out) {
    int rc = s->ops->invoke(s->conn, op, in, out);
    if (rc == TRANSPORT_FAIL) { s->last_errno = errno; return SVC_E_UNAVAILABLE; }
    return rc;
}
